function createPlayer(){if(avatar)scene.remove(avatar);avatar=makeHumanoid(false);avatar.position.set(0,0,0);scene.add(avatar);player={pos:new THREE.Vector3(0,0,0),health:100,armor:save.armorUpgrade?35:25, ammo:save.weapon==='Assault Rifle'?24:12,reserve:save.reserve||36};}
function setModeBase(){mode='base';$('#base-screen').classList.remove('hidden');$('#hud').classList.add('hidden');$('#result-screen').classList.add('hidden');$('#overlay').classList.add('hidden');buildEnvironment(true);if(avatar){scene.remove(avatar);avatar=null}const p=makeHumanoid(false);p.position.set(-2,0,8);p.rotation.y=-.3;scene.add(p);avatar=p;camera.position.set(-7,5.1,15);camera.lookAt(0,1.4,-3);updateBaseUI();}
function updateBaseUI(){if(!save)return;$('#base-credits').textContent=`₡ ${save.credits}`;$('#base-xp').textContent=`LVL ${String(save.level).padStart(2,'0')} · ${save.xp} XP`;$('#base-extractions').textContent=String(save.extractions).padStart(2,'0');$('#level-label').textContent=`LEVEL ${String(save.level).padStart(2,'0')}`;}
