function updateHUD(){if(!player)return;$('#health-text').textContent=Math.ceil(player.health);$('#health-fill').style.width=`${Math.max(0,player.health)}%`;$('#armor-text').textContent=Math.ceil(player.armor);$('#armor-fill').style.width=`${Math.min(100,player.armor/35*100)}%`;$('#ammo-now').textContent=player.ammo;$('#ammo-reserve').textContent=player.reserve;$('#weapon-label').textContent=save.weapon.toUpperCase();$('#haul-value').textContent=`₡ ${tempLoot.reduce((s,i)=>s+i.value,0)}`;$('#mission-timer').textContent=`${String(Math.floor(timeLeft/60)).padStart(2,'0')}:${String(Math.max(0,Math.floor(timeLeft%60))).padStart(2,'0')}`;$('#extract-dist').textContent=`${Math.round(player.pos.distanceTo(new THREE.Vector3(14,0,14)))}M`;$('#slot-count').textContent=`${tempLoot.length} / ${12+save.packUpgrade*3}`;$('#inventory-value').textContent=`₡ ${tempLoot.reduce((s,i)=>s+i.value,0)}`;$('#objective-title').textContent=extractProgress>0?'HOLD TO EXTRACT':'SECURE THE YARD';$('#objective-copy').textContent=extractProgress>0?`Keep holding… ${Math.max(0,3-extractProgress).toFixed(1)}s`:'Search containers · Extract to keep your haul';$('#interact-label').textContent=interactionPrompt();if(invOpen)renderFieldInventory();}
function interactionPrompt(){if(!player)return'USE';let near=containers.find(c=>!c.opened&&player.pos.distanceTo(new THREE.Vector3(c.x,0,c.z))<2.8);if(near)return'LOOT';if(player.pos.distanceTo(new THREE.Vector3(14,0,14))<3.2)return'EXTRACT';return'USE';}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');toastTimer=2.1;}
function renderFieldInventory(){const list=$('#loot-list');list.innerHTML='';if(!tempLoot.length){list.innerHTML='<div style="padding:16px 3px;color:#8e9da1;font:10px var(--mono)">BACKPACK EMPTY — FIND A CACHE</div>';return;}tempLoot.forEach((item,index)=>{const d=lootTypes[item.name]||{};const row=document.createElement('div');row.className='loot-row';row.innerHTML=`<div class="loot-icon" style="color:${d.color||'#c5d2d2'}">${d.icon||'◈'}</div><div class="loot-info"><b>${item.name}</b><small>${d.rarity||'FIELD ITEM'}</small></div><strong>₡ ${item.value}</strong>${item.name==='Med Patch'?'<button class="small-btn use-med" data-index="'+index+'">USE</button>':''}`;list.append(row);});list.querySelectorAll('.use-med').forEach(b=>b.onclick=()=>{const item=tempLoot.splice(+b.dataset.index,1)[0];player.health=Math.min(100,player.health+40);updateHUD();showToast('MED PATCH USED · +40 VITALS');});}

