function nearestContainer(){return containers.find(c=>!c.opened&&player.pos.distanceTo(new THREE.Vector3(c.x,0,c.z))<2.8)}
function doInteract(){if(mode!=='raid'||!player)return;const box=nearestContainer();if(box){box.opened=true;box.mesh.rotation.x=-.14;box.mesh.position.y=.12;const names=['Scrap Metal','Circuit Board','Med Patch','Ammo Pack','Power Cell','Data Core','Old World Token'];const n=1+(Math.random()<.32?1:0);for(let i=0;i<n;i++){if(tempLoot.length>=12+save.packUpgrade*3){showToast('BACKPACK FULL');break;}const name=names[Math.floor(Math.random()*names.length)];const item={name,value:lootTypes[name].value};tempLoot.push(item);if(name==='Ammo Pack')player.reserve+=12;}showToast(`CACHE OPENED · ${n} ITEM${n>1?'S':''} RECOVERED`);updateHUD();return;}}
function shoot(){if(mode!=='raid'||!player||!avatar)return;if(player.ammo<=0){showToast('EMPTY MAGAZINE · RELOAD');return}if(performance.now()-lastShot<(save.weapon==='Assault Rifle'?190:360))return;lastShot=performance.now();player.ammo--;updateHUD();const origin=avatar.position.clone().add(new THREE.Vector3(0,1.35,0));const dir=new THREE.Vector3(Math.sin(yaw),0,-Math.cos(yaw));if(aim)dir.y=-pitch*.4;const muzzle=origin.clone().add(dir.clone().multiplyScalar(.7));const flash=new THREE.Mesh(new THREE.SphereGeometry(.07,6,6),materials.yellow);flash.position.copy(muzzle);scene.add(flash);setTimeout(()=>scene.remove(flash),60);
  raycaster.set(origin,dir.normalize());raycaster.far=28;const hits=raycaster.intersectObjects(enemies,true);if(hits.length){let obj=hits[0].object;while(obj.parent&&!enemies.includes(obj))obj=obj.parent;if(enemies.includes(obj)){obj.userData.hp-=18+save.damageUpgrade*5+(save.weapon==='Assault Rifle'?5:0);const hitfx=new THREE.PointLight(0xff563e,6,2);hitfx.position.copy(hits[0].point);scene.add(hitfx);setTimeout(()=>scene.remove(hitfx),90);if(obj.userData.hp<=0)killEnemy(obj);}}}
function killEnemy(e){const i=enemies.indexOf(e);if(i<0)return;enemies.splice(i,1);world.remove(e);missionKills++;const credit=Math.floor(30+Math.random()*40);tempLoot.push({name:'Scrap Metal',value:credit});if(tempLoot.length>12+save.packUpgrade*3)tempLoot.pop();showToast(`HOSTILE DOWN · +${credit} SCRAP VALUE`);save.xp+=35;if(save.xp>=save.level*150){save.xp-=save.level*150;save.level++;showToast(`OPERATIVE PROMOTED · LEVEL ${save.level}`)}persist();updateHUD();}
function reload(){if(!player||mode!=='raid')return;if(player.ammo>=(save.weapon==='Assault Rifle'?24:12)||player.reserve<=0){showToast('MAGAZINE ALREADY FULL');return}const cap=save.weapon==='Assault Rifle'?24:12;const amount=Math.min(cap-player.ammo,player.reserve);player.ammo+=amount;player.reserve-=amount;$('#reload-state').textContent='RELOADED';setTimeout(()=>$('#reload-state').textContent='',700);updateHUD();}
function hurt(dmg){if(damageCooldown>0||mode!=='raid')return;damageCooldown=.35;const absorbed=Math.min(player.armor,dmg*.55);player.armor-=absorbed;player.health-=dmg-absorbed;$('#damage-flash').style.opacity='.8';setTimeout(()=>$('#damage-flash').style.opacity='0',100);updateHUD();if(player.health<=0)finishRaid(false,'Your signal disappeared in the yard. All unsecured loot was lost.');}
function finishRaid(success,copy=''){if(mode!=='raid')return;mode='result';shooting=false;interactHeld=false;$('#hud').classList.add('hidden');$('#result-screen').classList.remove('hidden');if(success){const haul=tempLoot.reduce((s,i)=>s+i.value,0);save.items.push(...tempLoot);save.extractions++;save.xp+=100+missionKills*20;if(save.xp>=save.level*150){save.xp-=save.level*150;save.level++;}persist();$('#result-tag').textContent='CONTRACT COMPLETE // EXTRACTION SUCCESS';$('#result-title').textContent='YOU MADE IT OUT';$('#result-copy').textContent=`Your haul is secure in storage. Visit the quartermaster to sell recovered items and improve your kit.`;$('#result-stats').innerHTML=`<div><small>SECURED HAUL</small><b style="color:var(--orange)">₡ ${haul}</b></div><div><small>HOSTILES</small><b>${missionKills}</b></div><div><small>EXPERIENCE</small><b>+${100+missionKills*20} XP</b></div>`;}else{$('#result-tag').textContent='CONTRACT FAILED // SIGNAL LOST';$('#result-title').textContent='OPERATIVE DOWN';$('#result-title').style.color='var(--red)';$('#result-copy').textContent=copy||'Mission time expired. All unsecured loot has been lost.';$('#result-stats').innerHTML=`<div><small>UNSECURED HAUL</small><b style="color:var(--red)">LOST</b></div><div><small>HOSTILES</small><b>${missionKills}</b></div><div><small>EXPERIENCE</small><b>+${missionKills*20} XP</b></div>`;save.xp+=missionKills*20;persist();}$('#return-btn').onclick=()=>{setModeBase();};}
function toggleInv(){invOpen=!invOpen;$('#inventory-panel').classList.toggle('hidden',!invOpen);if(invOpen)renderFieldInventory();}
function makePanel(type){const title=$('#dialog-title'),sub=$('#dialog-subtitle'),content=$('#dialog-content');content.innerHTML='';$('#overlay').classList.remove('hidden');
 if(type==='inventory'){title.textContent='STORAGE';sub.textContent='Extracted items are safe. Sell recovered goods for credits.';if(!save.items.length)content.innerHTML='<div class="storage-note">STORAGE IS EMPTY. Complete a contract and extract to secure your loot.</div>';else{save.items.forEach((item,i)=>{const d=lootTypes[item.name]||{};const row=document.createElement('div');row.className='base-inventory-row';row.innerHTML=`<span style="color:${d.color||'#74d8ca'}">${d.icon||'◈'}</span><strong>${item.name}</strong><small>₡ ${item.value}</small>`;content.append(row);});const sell=document.createElement('button');sell.className='sell-all';sell.innerHTML=`<span>SELL ALL SECURED LOOT</span><b>₡ ${save.items.reduce((s,i)=>s+i.value,0)}</b>`;sell.onclick=()=>{const value=save.items.reduce((s,i)=>s+i.value,0);save.credits+=value;save.items=[];persist();makePanel('inventory');};content.append(sell);}const note=document.createElement('div');note.className='storage-note';note.textContent=`CREDITS: ₡ ${save.credits}  ·  WEAPON: ${save.weapon}  ·  SPARE AMMO: ${save.reserve}`;content.append(note);}
 if(type==='shop'){title.textContent='QUARTERMASTER';sub.textContent=`Field supplies and hardware · Available credits: ₡ ${save.credits}`;const goods=[['Ammo Refill','▤','Top up your reserve ammunition.','₡ 45',()=>{save.credits-=45;save.reserve+=36;}],['Med Patch','✚','Restore 40 health on your next run.','₡ 65',()=>{save.credits-=65;save.items.push({name:'Med Patch',value:0});}],['Assault Rifle','⌁','24-round magazine · higher fire rate.','₡ 420',()=>{save.credits-=420;save.weapon='Assault Rifle';}],['Armor Plates','⬡','Reinforce your next deployment.','₡ 110',()=>{save.credits-=110;save.armor=35;}]];renderGoods(goods);}
 if(type==='upgrade'){title.textContent='AUGMENTATION';sub.textContent=`Permanent operative improvements · Available credits: ₡ ${save.credits}`;const upgrades=[['Weapon Tuning','⌁',`Damage +5 per level · CURRENT ${save.damageUpgrade}`,200+save.damageUpgrade*180,()=>save.damageUpgrade++],['Reinforced Plating','⬡',`Armor +10 · CURRENT ${save.armorUpgrade}`,180+save.armorUpgrade*170,()=>{save.armorUpgrade++;save.armor=35;}],['Expanded Pack','▤',`+3 field slots · CURRENT ${12+save.packUpgrade*3} SLOTS`,160+save.packUpgrade*160,()=>save.packUpgrade++]];upgrades.forEach(([name,icon,desc,cost,buy])=>{const row=document.createElement('div');row.className='upgrade-card';row.innerHTML=`<div class="upgrade-symbol">${icon}</div><div class="upgrade-text"><b>${name}</b><small>${desc}</small></div><button class="small-btn" ${save.credits<cost?'disabled':''}>₡ ${cost} · INSTALL</button>`;row.querySelector('button').onclick=()=>{if(save.credits<cost)return;save.credits-=cost;buy();persist();makePanel('upgrade');};content.append(row);});}
}
function renderGoods(goods){const grid=document.createElement('div');grid.className='shop-grid';goods.forEach(([name,icon,desc,price,buy])=>{const cost=+price.replace(/\D/g,'');const card=document.createElement('div');card.className='shop-card';card.innerHTML=`<div><span class="item-icon">${icon}</span><span class="item-icon" style="font:9px var(--mono);color:#e4ad6a">${price}</span></div><h3>${name}</h3><p>${desc}</p><div class="buy-row"><span>SUPPLY</span><button class="small-btn" ${save.credits<cost?'disabled':''}>PURCHASE</button></div>`;card.querySelector('button').onclick=()=>{if(save.credits<cost)return;save.credits-=cost;buy();persist();makePanel('shop');};grid.append(card);});$('#dialog-content').append(grid);const storage=document.createElement('button');storage.className='sell-all';storage.innerHTML=`<span>SELL SECURED STORAGE (${save.items.length} ITEMS)</span><b>₡ ${save.items.reduce((s,i)=>s+i.value,0)}</b>`;storage.onclick=()=>{if(!save.items.length){showToast('NO SECURED GOODS TO SELL');return;}const total=save.items.reduce((s,i)=>s+i.value,0);save.credits+=total;save.items=[];persist();makePanel('shop');};$('#dialog-content').append(storage);}

