function updateEnemies(dt){const target=player.pos;for(const e of enemies){const p=e.position;const d=p.distanceTo(target);let dir=new THREE.Vector3();if(d<12){dir.set(target.x-p.x,0,target.z-p.z).normalize();if(d>2.7){p.addScaledVector(dir,e.userData.speed*dt);}}else{e.userData.patrol+=dt;const a=e.userData.phase+Math.sin(e.userData.patrol*.5)*.8;const goal=e.userData.home.clone().add(new THREE.Vector3(Math.cos(a)*2.1,0,Math.sin(a)*2.1));dir.set(goal.x-p.x,0,goal.z-p.z);if(dir.length()>.3)p.addScaledVector(dir.normalize(),e.userData.speed*.35*dt);}
 if(dir.lengthSq()>.01)e.rotation.y=Math.atan2(dir.x,dir.z);e.userData.attackTimer-=dt;if(d<9&&e.userData.attackTimer<=0){e.userData.attackTimer=e.userData.kind===0?1.4:e.userData.kind===1?1.15:1.75;const start=p.clone().add(new THREE.Vector3(0,1.3,0));const end=target.clone().add(new THREE.Vector3(0,1,0));const beam=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,start.distanceTo(end),5),new THREE.MeshBasicMaterial({color:e.userData.kind===2?0xf08b4d:0xf05248}));beam.position.copy(start).add(end).multiplyScalar(.5);beam.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),end.sub(start).normalize());scene.add(beam);setTimeout(()=>scene.remove(beam),100);if(d<7.5)hurt(e.userData.damage);}}
