@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700&display=swap');
:root{--bg:#080d12;--panel:rgba(9,16,22,.92);--line:rgba(175,204,215,.15);--muted:#81909a;--white:#eaf1f2;--cyan:#76e3d3;--orange:#f2a35a;--red:#f05b56;--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif}
*{box-sizing:border-box}
html,body,#game-root{width:100%;height:100%;margin:0;overflow:hidden;background:var(--bg);color:var(--white)}
body{font-family:Inter,Arial,sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}
button{color:inherit;font:inherit;cursor:pointer}
#game-root{position:relative}
#game{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 53% 47%,transparent 42%,rgba(1,5,8,.35) 100%),linear-gradient(180deg,rgba(3,8,11,.42),transparent 25%,transparent 67%,rgba(2,7,10,.64))}
.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:17px 30px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(211,233,238,.09);background:linear-gradient(180deg,rgba(5,10,14,.68),transparent)}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{display:grid;place-items:center;width:37px;height:37px;border:1px solid var(--cyan);color:var(--cyan);font:800 24px var(--display);transform:skew(-8deg)}
.brand b{font:800 20px var(--display);letter-spacing:1.6px}
.brand b span{font-weight:500;color:#aab8bf}
.brand small,.profile small{display:block;color:#809099;font:9px var(--mono);letter-spacing:1.2px;margin-top:3px}
.top-right{display:flex;align-items:center;gap:28px}
.network{font:9px var(--mono);letter-spacing:1px;color:#a7b3b8}
.network i,.eyebrow i{display:inline-block;width:6px;height:6px;background:var(--cyan);border-radius:50%;box-shadow:0 0 9px var(--cyan);margin-right:7px}
.profile{display:flex;align-items:center;gap:10px;border-left:1px solid var(--line);padding-left:20px;font-size:10px;letter-spacing:1px}
.rank{display:grid;place-items:center;color:var(--orange);border:1px solid #66533e;width:30px;height:30px;font:700 16px var(--display)}
.base-screen{position:absolute;z-index:2;inset:0;pointer-events:none}
.base-copy{position:absolute;left:7.5%;top:19%;max-width:430px;pointer-events:auto}
.eyebrow{font:10px var(--mono);letter-spacing:1.5px;color:var(--cyan)}
.base-copy h1{font:900 clamp(60px,8vw,105px)/.79 var(--display);letter-spacing:1px;margin:20px 0 18px;text-shadow:0 8px 36px #071014}
.base-copy h1 em{font-style:normal;color:var(--cyan)}
.base-copy>p{color:#bac5c9;font-size:14px;line-height:1.7;margin:0 0 25px}
.base-stats{display:flex;gap:27px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:13px 0;margin-bottom:23px}
.base-stats>div{display:flex;flex-direction:column;gap:6px}
.base-stats small{font:9px var(--mono);color:#829098;letter-spacing:1px}
.base-stats b{font:600 14px var(--mono);color:#e6eeef}
.primary-btn{height:51px;min-width:290px;padding:0 17px;border:1px solid #90eadc;background:linear-gradient(105deg,rgba(105,208,190,.23),rgba(74,146,148,.1));color:#dffdf5;text-align:left;font:700 12px var(--mono);letter-spacing:1px;box-shadow:0 0 25px rgba(90,209,187,.09);transition:.2s}
.primary-btn:hover{background:rgba(105,208,190,.34);box-shadow:0 0 32px rgba(90,209,187,.23);transform:translateY(-1px)}
.primary-btn>span{font-size:10px;margin-right:12px;color:var(--cyan)}
.primary-btn i{float:right;font-style:normal;color:var(--cyan)}
.base-hint{margin-top:14px;color:#819097;font:9px var(--mono);letter-spacing:1px}
.base-hint span{color:#d5dcdb;margin-left:10px}
.base-nav{position:absolute;right:6.5%;bottom:16%;display:flex;gap:8px;pointer-events:auto}
.nav-btn{min-width:152px;padding:14px 13px;background:rgba(8,15,20,.78);border:1px solid var(--line);font:10px var(--mono);letter-spacing:.8px;backdrop-filter:blur(8px);transition:.18s}
.nav-btn span{display:inline-block;font-size:16px;color:var(--cyan);margin-right:8px;vertical-align:-2px}
.nav-btn:hover{border-color:var(--cyan);background:rgba(21,42,45,.85)}
.base-location{position:absolute;right:30px;bottom:30px;text-align:right;display:flex;flex-direction:column;gap:4px}
.base-location b{font:700 11px var(--mono);letter-spacing:1.4px}
.base-location small{font:9px var(--mono);color:#86959c;letter-spacing:1px}
.location-line{height:1px;background:linear-gradient(90deg,transparent,var(--cyan));margin-bottom:5px}
.hidden{display:none!important}
.hud{position:absolute;z-index:2;inset:0;pointer-events:none}
.hud button,.inventory-panel{pointer-events:auto}
.mission-card{position:absolute;left:25px;top:93px;background:rgba(7,14,19,.78);border:1px solid var(--line);display:flex;align-items:center;gap:12px;padding:10px 14px;backdrop-filter:blur(7px)}
.mission-icon{font-size:23px;color:var(--cyan)}
.mission-card small,.player-readout span,.weapon-name small{display:block;color:#91a1a6;font:9px var(--mono);letter-spacing:1px}
.mission-card b{display:block;margin-top:4px;font:600 18px var(--mono)}
.mission-divider{height:29px;width:1px;background:var(--line);margin:0 5px}
.objective{position:absolute;left:50%;top:92px;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:9px 14px;background:rgba(7,14,19,.62);border:1px solid rgba(185,216,220,.12);min-width:270px}
.obj-dot{width:8px;height:8px;background:var(--orange);box-shadow:0 0 12px var(--orange);transform:rotate(45deg)}
.objective b{font:700 11px var(--mono);letter-spacing:.7px}
.objective small{display:block;color:#9eaaad;font-size:10px;margin-top:3px}
.hud-right{position:absolute;right:24px;top:91px;display:flex;align-items:center;gap:8px}
.loot-chip,.icon-btn{background:rgba(7,14,19,.78);border:1px solid var(--line);padding:11px 13px;font:10px var(--mono);letter-spacing:.6px}
.loot-chip b{color:var(--orange);margin-left:7px}
.icon-btn{font-size:17px;color:var(--cyan)}
.icon-btn span{font:9px var(--mono);color:#dbe5e5;margin-left:3px}
.player-readout{position:absolute;bottom:27px;left:26px;width:205px;background:rgba(7,14,19,.68);padding:11px 13px;border:1px solid var(--line)}
.health-row,.armor-row{display:flex;align-items:center;justify-content:space-between}
.health-row b,.armor-row b{font:13px var(--mono)}
.health-track,.armor-track{height:5px;background:#283238;margin:7px 0 8px}
.health-track i,.armor-track i{height:100%;width:100%;display:block;background:var(--cyan);transition:width .2s}
.armor-row{gap:7px}
.armor-row span{font-size:8px}
.armor-row b{font-size:10px}
.armor-track{flex:1;height:3px;margin:0}
.armor-track i{background:#83a8e3}
.weapon-readout{position:absolute;right:26px;bottom:27px;text-align:right;padding:10px 13px;background:rgba(7,14,19,.68);border:1px solid var(--line);min-width:158px}
.weapon-name{display:flex;justify-content:space-between;align-items:center;gap:8px}
.ammo{display:flex;justify-content:flex-end;align-items:baseline;gap:5px;margin-top:3px}
.ammo>b{font:500 32px var(--display);line-height:1;color:#f4f8f6}
.ammo>span{font:12px var(--mono);color:#859399}
.ammo>span i{font-style:normal}
.tiny-button{border:1px solid var(--line);background:#152027;color:var(--cyan);font:10px var(--mono);padding:4px 7px;margin-left:5px}
.crosshair{position:absolute;left:50%;top:50%;width:17px;height:17px;transform:translate(-50%,-50%);opacity:.85}
.crosshair i,.crosshair b,.crosshair em{position:absolute;display:block;background:#b9e8dd;box-shadow:0 0 4px #75decf}
.crosshair i:first-child{width:1px;height:6px;left:8px;top:0}
.crosshair i:nth-child(3){width:1px;height:6px;left:8px;bottom:0}
.crosshair b{height:1px;width:6px;left:0;top:8px}
.crosshair em{height:1px;width:6px;right:0;top:8px}
.toast{position:absolute;left:50%;top:62%;transform:translate(-50%,0);color:#e6f4f1;font:11px var(--mono);letter-spacing:1px;background:rgba(5,12,16,.85);border:1px solid rgba(118,227,211,.4);padding:9px 14px;opacity:0;transition:.2s}
.toast.show{opacity:1;transform:translate(-50%,-7px)}
.inventory-panel{position:absolute;right:24px;top:150px;width:320px;max-height:calc(100% - 300px);overflow:auto;background:rgba(8,15,21,.94);border:1px solid rgba(136,194,194,.28);backdrop-filter:blur(14px);padding:16px}
.panel-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:12px}
.panel-head small{font:9px var(--mono);letter-spacing:1.3px;color:var(--cyan)}
.panel-head h2{font:700 23px var(--display);letter-spacing:1px;margin:3px 0 0}
.panel-head h2 span{font:9px var(--mono);color:#97a4a8;margin-left:7px}
.close-btn{border:0;background:transparent;color:#9ca9ad;font-size:23px;padding:0 3px}
.loot-list{padding:9px 0}
.loot-row{display:flex;align-items:center;gap:10px;padding:9px 5px;border-bottom:1px solid rgba(184,210,212,.08)}
.loot-icon{width:31px;height:31px;display:grid;place-items:center;background:rgba(112,201,187,.1);color:var(--cyan);font-size:16px}
.loot-info{flex:1}
.loot-info b{font:600 11px var(--mono);display:block}
.loot-info small{color:#87969b;font:9px var(--mono)}
.loot-row>strong{font:11px var(--mono);color:var(--orange)}
.inventory-foot{display:flex;justify-content:space-between;padding-top:10px;color:#96a3a7;font:9px var(--mono);letter-spacing:.8px}
.inventory-foot b{color:var(--orange);font-size:12px}
.desktop-help{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);color:rgba(194,208,208,.64);font:9px var(--mono);letter-spacing:.6px;white-space:nowrap}
.desktop-help span{color:var(--cyan);padding:0 5px}
.mobile-controls{display:none;pointer-events:none}
.stick-zone{position:absolute;bottom:38px;left:24px;width:144px;height:144px;pointer-events:auto;touch-action:none}
.stick-base{position:absolute;left:5px;bottom:6px;width:110px;height:110px;border:1px solid rgba(189,224,222,.32);background:rgba(17,30,35,.38);border-radius:50%;display:grid;place-items:center;backdrop-filter:blur(4px)}
#stick-knob{width:48px;height:48px;background:rgba(135,209,198,.34);border:1px solid rgba(184,251,238,.66);border-radius:50%;box-shadow:0 0 18px rgba(89,213,196,.15)}
